        if (callingTask.getWindowingMode() == WINDOWING_MODE_FULLSCREEN
                || getSplitPosition(callingTask.taskId) == SPLIT_POSITION_TOP_OR_LEFT) {
            return SPLIT_POSITION_BOTTOM_OR_RIGHT;
